20	const (
21		ChildOf     = "child-of"
22		FollowsFrom = "follows-from"
23	
24		StringType  = "string"
25		BoolType    = "bool"
26		Int64Type   = "int64"
27		Float64Type = "float64"
28		BinaryType  = "binary"
29	)
