31	// Span is the database representation of a span.
32	type Span struct {
33		TraceID       TraceID
34		SpanID        int64
35		ParentID      int64 // deprecated
36		OperationName string
37		Flags         int32
38		StartTime     int64 // microseconds since epoch
39		Duration      int64 // microseconds
40		Tags          []KeyValue
41		Logs          []Log
42		Refs          []SpanRef
43		Process       Process
44		ServiceName   string
45		SpanHash      int64
46	}
47	
48	// Hash implements Hash from Hashable.
49	func (s Span) Hash(w io.Writer) (err error) {
50		sCopy := s
51		sCopy.SpanHash = 0
52		enc := gob.NewEncoder(w)
53		return enc.Encode(sCopy)
54	}
