31	// ToDBModel translates internal trace data into the DB Spans.
32	// Returns a slice of translated DB Spans.
33	func ToDBModel(td ptrace.Traces) []dbmodel.Span {
34		resourceSpans := td.ResourceSpans()
35	
36		if resourceSpans.Len() == 0 {
37			return []dbmodel.Span{}
38		}
39	
40		batches := make([]dbmodel.Span, 0, td.SpanCount())
41		for i := 0; i < resourceSpans.Len(); i++ {
42			rs := resourceSpans.At(i)
43			batch := resourceSpansToDbSpans(rs)
44			batches = append(batches, batch...)
45		}
46	
47		return batches
48	}
49	
50	func resourceSpansToDbSpans(resourceSpans ptrace.ResourceSpans) []dbmodel.Span {
51		resource := resourceSpans.Resource()
52		scopeSpans := resourceSpans.ScopeSpans()
53	
54		if scopeSpans.Len() == 0 {
55			return []dbmodel.Span{}
56		}
57	
58		process := resourceToDbProcess(resource)
59	
60		// Approximate the number of the spans as the number of the spans in the first
61		// instrumentation library info.
62		dbSpans := make([]dbmodel.Span, 0, scopeSpans.At(0).Spans().Len())
63	
64		for _, scopeSpan := range scopeSpans.All() {
65			for _, span := range scopeSpan.Spans().All() {
66				dbSpan := spanToDbSpan(span, scopeSpan.Scope(), process)
67				dbSpans = append(dbSpans, dbSpan)
68			}
69		}
70	
71		return dbSpans
72	}
73	
74	func resourceToDbProcess(resource pcommon.Resource) dbmodel.Process {
75		process := dbmodel.Process{}
76		attrs := resource.Attributes()
77		process.ServiceName = noServiceName
78		if attrs.Len() == 0 {
79			return process
80		}
81		tags := make([]dbmodel.KeyValue, 0, attrs.Len())
82		for key, attr := range attrs.All() {
83			if key == otelsemconv.ServiceNameKey {
84				process.ServiceName = attr.AsString()
85				continue
86			}
87			tags = append(tags, attributeToDbTag(key, attr))
88		}
89		process.Tags = tags
90		dbmodel.SortKVs(process.Tags)
91		return process
92	}
93	
94	func appendTagsFromAttributes(tags []dbmodel.KeyValue, attrs pcommon.Map) []dbmodel.KeyValue {
95		if attrs.Len() == 0 {
96			return tags
97		}
98		for key, attr := range attrs.All() {
99			tags = append(tags, attributeToDbTag(key, attr))
100		}
101		return tags
102	}
103	
104	func attributeToDbTag(key string, attr pcommon.Value) dbmodel.KeyValue {
105		tag := dbmodel.KeyValue{Key: key}
106		switch attr.Type() {
107		case pcommon.ValueTypeInt:
108			tag.ValueType = dbmodel.Int64Type
109			tag.ValueInt64 = attr.Int()
110		case pcommon.ValueTypeBool:
111			tag.ValueType = dbmodel.BoolType
112			tag.ValueBool = attr.Bool()
113		case pcommon.ValueTypeDouble:
114			tag.ValueType = dbmodel.Float64Type
115			tag.ValueFloat64 = attr.Double()
116		case pcommon.ValueTypeBytes:
117			tag.ValueType = dbmodel.BinaryType
118			tag.ValueBinary = attr.Bytes().AsRaw()
119		case pcommon.ValueTypeMap, pcommon.ValueTypeSlice:
120			tag.ValueType = dbmodel.StringType
121			tag.ValueString = attr.AsString()
122		default:
123			tag.ValueType = dbmodel.StringType
124			tag.ValueString = attr.Str()
125		}
126		return tag
127	}
