129	func spanToDbSpan(span ptrace.Span, scope pcommon.InstrumentationScope, process dbmodel.Process) dbmodel.Span {
130		dbTraceId := dbmodel.TraceID(span.TraceID())
131		dbReferences := linksToDbSpanRefs(span.Links(), spanIDToDbSpanId(span.ParentSpanID()), dbTraceId)
132		startTime := span.StartTimestamp().AsTime()
133		dbSpan := dbmodel.Span{
134			TraceID:       dbTraceId,
135			SpanID:        spanIDToDbSpanId(span.SpanID()),
136			OperationName: span.Name(),
137			Refs:          dbReferences,
138			//nolint:gosec // G115 // OTLP timestamp is nanoseconds since epoch (semantically non-negative), safe to convert to int64 microseconds
139			StartTime: int64(model.TimeAsEpochMicroseconds(startTime)),
140			//nolint:gosec // G115 // span.EndTime - span.StartTime is guaranteed non-negative by schema constraints
141			Duration: int64(model.DurationAsMicroseconds(span.EndTimestamp().AsTime().Sub(startTime))),
142			Tags:     getDbTags(span, scope),
143			Logs:     spanEventsToDbLogs(span.Events()),
144			Process:  process,
145			//nolint:gosec // G115 // span.Flags is uint32, converting to int32 for DB storage (semantically non-negative, fits in int32)
146			Flags:       int32(span.Flags()),
147			ServiceName: process.ServiceName,
148			ParentID:    spanIDToDbSpanId(span.ParentSpanID()),
149		}
150		spanHash, _ := model.HashCode(dbSpan)
151		//nolint:gosec // G115
152		dbSpan.SpanHash = int64(spanHash)
153		return dbSpan
154	}
