17		storageMode storageMode
18		indexFilter dbmodel.IndexFilter
19	}
20	
21	// TagFilter can be provided to filter any tags that should not be indexed.
22	func TagFilter(tagFilter dbmodel.TagFilter) Option {
23		return func(o *Options) {
24			o.tagFilter = tagFilter
25		}
26	}
27	
28	// StoreIndexesOnly can be provided to skip storing spans, and only store span indexes.
29	func StoreIndexesOnly() Option {
30		return func(o *Options) {
31			o.storageMode = indexFlag
32		}
33	}
34	
35	// StoreWithoutIndexing can be provided to store spans without indexing them.
36	func StoreWithoutIndexing() Option {
37		return func(o *Options) {
38			o.storageMode = storeFlag
39		}
40	}
41	
42	// IndexFilter can be provided to filter certain spans that should not be indexed.
43	func IndexFilter(indexFilter dbmodel.IndexFilter) Option {
44		return func(o *Options) {
45			o.indexFilter = indexFilter
46		}
47	}
48	
49	func applyOptions(opts ...Option) Options {
50		o := Options{}
51		for _, opt := range opts {
52			opt(&o)
53		}
