55			o.tagFilter = dbmodel.DefaultTagFilter
56		}
57		if o.storageMode == 0 {
58			o.storageMode = storeFlag | indexFlag
59		}
60		if o.indexFilter == nil {
61			o.indexFilter = dbmodel.DefaultIndexFilter
62		}
63		return o
