// TraceWriter implements tracestore.Writer by converting OTLP traces into
// Cassandra dbmodel spans and delegating writes to a CoreSpanWriter.
type TraceWriter struct {
	writer spanstore.CoreSpanWriter
}

// NewTraceWriter creates a TraceWriter backed by a new Cassandra SpanWriter.
func NewTraceWriter(
	session cassandra.Session,
	writeCacheTTL time.Duration,
	metricsFactory metrics.Factory,
	logger *zap.Logger,
	options ...spanstore.Option,
) (*TraceWriter, error) {
	writer, err := spanstore.NewSpanWriter(session, writeCacheTTL, metricsFactory, logger, options...)
	if err != nil {
		return nil, err
	}
	return &TraceWriter{writer: writer}, nil
}

// WriteTraces converts the given OTLP traces to dbmodel spans and writes each of
// them, collecting any errors encountered.
func (w *TraceWriter) WriteTraces(_ context.Context, td ptrace.Traces) error {
	dbSpans := ToDBModel(td)
	var errs []error
	for i := range dbSpans {
		errs = append(errs, w.writer.WriteSpan(&dbSpans[i]))
	}
	return errors.Join(errs...)
}

// Close closes the underlying span writer.
func (w *TraceWriter) Close() error {
	return w.writer.Close()
}
