65	func (f *Factory) CreateTraceWriter() (tracestore.Writer, error) {
66		options, err := writerOptions(f.v1Factory.Options)
67		if err != nil {
68			return nil, err
69		}
70		return ctracestore.NewTraceWriter(
71			f.v1Factory.GetSession(),
72			f.v1Factory.Options.SpanStoreWriteCacheTTL,
73			f.metricsFactory,
74			f.logger,
75			options...,
76		)
77	}
