79	func writerOptions(opts *cassandra.Options) ([]cspanstore.Option, error) {
80		var tagFilters []dbmodel.TagFilter
81	
82		// drop all tag filters
83		if !opts.Index.Tags || !opts.Index.ProcessTags || !opts.Index.Logs {
84			tagFilters = append(tagFilters, dbmodel.NewTagFilterDropAll(!opts.Index.Tags, !opts.Index.ProcessTags, !opts.Index.Logs))
85		}
86	
87		// black/white list tag filters
88		tagIndexBlacklist := opts.TagIndexBlacklist()
89		tagIndexWhitelist := opts.TagIndexWhitelist()
90		if len(tagIndexBlacklist) > 0 && len(tagIndexWhitelist) > 0 {
91			return nil, errors.New("only one of TagIndexBlacklist and TagIndexWhitelist can be specified")
92		}
93		if len(tagIndexBlacklist) > 0 {
94			tagFilters = append(tagFilters, dbmodel.NewBlacklistFilter(tagIndexBlacklist))
95		} else if len(tagIndexWhitelist) > 0 {
96			tagFilters = append(tagFilters, dbmodel.NewWhitelistFilter(tagIndexWhitelist))
97		}
98	
99		if len(tagFilters) == 0 {
100			return nil, nil
101		} else if len(tagFilters) == 1 {
102			return []cspanstore.Option{cspanstore.TagFilter(tagFilters[0])}, nil
103		}
104	
105		return []cspanstore.Option{cspanstore.TagFilter(dbmodel.NewChainedTagFilter(tagFilters...))}, nil
106	}
